"use client";

import { useEffect, useState } from "react";

/**
 * The height of the on-screen keyboard on a phone's browser, or 0 while it is hidden. It measures how
 * much of the layout viewport the visual viewport has lost, which is what the keyboard covers. It is
 * always 0 on desktop, and while the page is pinch-zoomed, because a zoom also shrinks the visual
 * viewport and would be mistaken for a keyboard.
 */
export function useKeyboardHeight(): number {
  const [height, setHeight] = useState(0);

  useEffect(() => {
    const viewport = window.visualViewport;
    if (!viewport) return;
    const update = () =>
      setHeight(
        viewport.scale > 1
          ? 0
          : Math.max(0, Math.round(window.innerHeight - viewport.height - viewport.offsetTop)),
      );
    update();
    viewport.addEventListener("resize", update);
    viewport.addEventListener("scroll", update);
    return () => {
      viewport.removeEventListener("resize", update);
      viewport.removeEventListener("scroll", update);
    };
  }, []);

  return height;
}

import { useEffect, useState } from "react";
import { Keyboard, Platform } from "react-native";

/**
 * The height of the on-screen keyboard, or 0 while it is hidden. On iOS it updates as the keyboard
 * starts to move, so a view can slide up alongside it; on Android it updates once the keyboard has
 * finished appearing. Always 0 on the web, where there is no on-screen keyboard to measure.
 */
export function useKeyboardHeight(): number {
  const [height, setHeight] = useState(0);

  useEffect(() => {
    const ios = Platform.OS === "ios";
    const show = Keyboard.addListener(ios ? "keyboardWillShow" : "keyboardDidShow", (event) =>
      setHeight(event.endCoordinates.height),
    );
    const hide = Keyboard.addListener(ios ? "keyboardWillHide" : "keyboardDidHide", () =>
      setHeight(0),
    );
    return () => {
      show.remove();
      hide.remove();
    };
  }, []);

  return height;
}
